public final class Solution {
    private Solution() {
    }

    public static int[] scaleReadings(
            int[] readings,
            int numerator,
            int denominator,
            int lowerBound,
            int upperBound) {
        int[] result = new int[readings.length];
        for (int i = 0; i < readings.length; i++) {
            int scaled = readings[i] * numerator / denominator;
            if (scaled < lowerBound) {
                scaled = lowerBound;
            } else if (scaled > upperBound) {
                scaled = upperBound;
            }
            result[i] = scaled;
        }
        return result;
    }
}
